package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.JdbcCollectorHeartbeats;import com.lianxibu.site.domain.protocol.*;
import java.nio.charset.StandardCharsets;import java.time.*;import java.util.UUID;import javax.sql.DataSource;import org.h2.jdbcx.JdbcDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.junit.jupiter.api.*;
class CollectorHeartbeatsNativeTest {
 DataSource db;JdbcTemplate jdbc;TransactionTemplate tx;JdbcCollectorHeartbeats store;String node;Instant now=Instant.parse("2026-01-01T00:10:00Z");
 DataSource source(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:collector-heartbeat-"+System.nanoTime()+";MODE=MySQL;DB_CLOSE_DELAY=-1");return ds;}
 @BeforeEach void setup()throws Exception{db=source();jdbc=new JdbcTemplate(db);boolean h2=db instanceof JdbcDataSource;String json=h2?"CLOB":"JSON",time=h2?"TIMESTAMP(6)":"DATETIME(6)";jdbc.execute("CREATE TABLE IF NOT EXISTS runtime_settings(setting_key VARCHAR(64) PRIMARY KEY,value_json "+json+" NOT NULL,revision BIGINT NOT NULL,updated_at "+time+" NOT NULL)");jdbc.execute("CREATE TABLE IF NOT EXISTS collector_nodes(id VARCHAR(64) PRIMARY KEY,name VARCHAR(100),token_hash BINARY(32) UNIQUE,allowed_source_ids "+json+",permissions_json "+json+",enabled INT,last_seen_at "+time+",config_revision BIGINT)");node=UUID.randomUUID().toString();jdbc.update("INSERT INTO collector_nodes(id,name,token_hash,allowed_source_ids,permissions_json,enabled,config_revision) VALUES(?, ?, ?, '[]','[\"heartbeat:write\"]',1,1)",node,"Fictional native heartbeat",java.security.MessageDigest.getInstance("SHA-256").digest(node.getBytes(StandardCharsets.UTF_8)));tx=new TransactionTemplate(new DataSourceTransactionManager(db));store=new JdbcCollectorHeartbeats(db);}
 @AfterEach void cleanup(){if(jdbc!=null&&node!=null){jdbc.update("DELETE FROM runtime_settings WHERE setting_key=?",JdbcCollectorHeartbeats.key(node));jdbc.update("DELETE FROM collector_nodes WHERE id=?",node);}}
 CollectorHeartbeatTelemetry.Parsed body(Instant at,long bytes){var root=tools.jackson.databind.json.JsonMapper.shared().createObjectNode();root.put("observed_at",new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(at));root.put("pending_observations",0);root.put("pending_controls",0);root.put("quarantined",0);root.put("outbox_bytes",bytes);root.put("free_bytes",2L<<30);root.putNull("oldest_pending_at");return CollectorHeartbeatTelemetry.parse(CanonicalJson.bytes(root));}
 JdbcCollectorHeartbeats.Entry save(Instant at,long bytes){return tx.execute(s->store.save(node,1,body(at,bytes),at));}
 @Test void actualNativeHistoryAndOriginalLastSeenCommitTogetherAndReplayNeverRefreshesTime(){var original=save(now,10);assertEquals(original,tx.execute(s->store.save(node,1,body(now,10),now.plusSeconds(60))));var history=tx.execute(s->store.latest(node,1));assertEquals(1,history.revision());assertEquals(1,history.samples().size());assertEquals(original,history.latest());assertEquals(now,jdbc.queryForObject("SELECT last_seen_at FROM collector_nodes WHERE id=?",java.sql.Timestamp.class,node).toInstant());assertFalse(history.toString().contains(node));assertThrows(UnsupportedOperationException.class,()->history.samples().clear());}
 @Test void onlyLatestThreeCompleteOriginalHeartbeatsRemainAndOldAckCannotRefreshNewPointer(){var original=save(now,10);save(now.plusSeconds(60),11);save(now.plusSeconds(120),12);assertEquals(original,tx.execute(s->store.save(node,1,body(now,10),now.plusSeconds(180))));save(now.plusSeconds(180),13);var history=tx.execute(s->store.latest(node,1));assertEquals(3,history.samples().size());assertEquals(now.plusSeconds(60),history.samples().getFirst().input().sample().observedAt());assertEquals(4,history.revision());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM runtime_settings WHERE setting_key=?",Integer.class,JdbcCollectorHeartbeats.key(node)));assertThrows(IllegalStateException.class,()->save(now,10));}
 @Test void sameTimeDifferentBodyFutureClockRollbackAndStaleSequenceAreRejected(){save(now,10);assertThrows(IllegalStateException.class,()->save(now,11));assertThrows(IllegalStateException.class,()->save(now.minusSeconds(1),10));assertThrows(IllegalStateException.class,()->tx.execute(s->store.save(node,1,body(now.plusSeconds(1),12),now)));assertEquals(1L,tx.execute(s->store.latest(node,1)).revision());}
 @Test void actualNativeNodeRevisionChangeRequiresNewHistoryAndCannotUseOldTokenProof(){save(now,10);jdbc.update("UPDATE collector_nodes SET config_revision=2 WHERE id=?",node);assertNull(tx.execute(s->store.latest(node,2)));var entry=tx.execute(s->store.save(node,2,body(now.plusSeconds(60),11),now.plusSeconds(60)));assertEquals(1,tx.execute(s->store.latest(node,2)).samples().size());assertEquals(entry,tx.execute(s->store.latest(node,2)).latest());assertThrows(IllegalStateException.class,()->tx.execute(s->store.latest(node,1)));assertThrows(IllegalStateException.class,()->save(now.plusSeconds(120),12));}
 @Test void changedHashClosedFieldsCapacityAndUpdatedTimeNeverProduceHealthyHistory(){save(now,10);String encoded=jdbc.queryForObject("SELECT value_json FROM runtime_settings WHERE setting_key=?",String.class,JdbcCollectorHeartbeats.key(node));var parsed=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(encoded);((tools.jackson.databind.node.ObjectNode)parsed.get("samples").get(0)).put("payload_hash","0".repeat(64));jdbc.update("UPDATE runtime_settings SET value_json=? WHERE setting_key=?",parsed.toString(),JdbcCollectorHeartbeats.key(node));assertThrows(IllegalStateException.class,()->tx.execute(s->store.latest(node,1)));parsed=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(encoded);parsed.put("unknown",true);jdbc.update("UPDATE runtime_settings SET value_json=? WHERE setting_key=?",parsed.toString(),JdbcCollectorHeartbeats.key(node));assertThrows(IllegalArgumentException.class,()->tx.execute(s->store.latest(node,1)));jdbc.update("UPDATE runtime_settings SET value_json=? WHERE setting_key=?","{\"oversized\":\""+"x".repeat(8192)+"\"}",JdbcCollectorHeartbeats.key(node));assertThrows(IllegalStateException.class,()->tx.execute(s->store.latest(node,1)));jdbc.update("UPDATE runtime_settings SET value_json=?,updated_at=? WHERE setting_key=?",encoded,java.sql.Timestamp.from(now.plusSeconds(1)),JdbcCollectorHeartbeats.key(node));assertThrows(IllegalStateException.class,()->tx.execute(s->store.latest(node,1)));}
 @Test void failedNodeCasOrTransactionRollbackLeavesNoHealthyHistory(){jdbc.update("UPDATE collector_nodes SET enabled=0 WHERE id=?",node);assertThrows(IllegalStateException.class,()->save(now,10));assertNull(tx.execute(s->store.latest(node,1)));jdbc.update("UPDATE collector_nodes SET enabled=1 WHERE id=?",node);assertThrows(IllegalStateException.class,()->tx.execute(s->{store.save(node,1,body(now,10),now);throw new IllegalStateException("fictional rollback");}));assertNull(tx.execute(s->store.latest(node,1)));assertNull(jdbc.queryForObject("SELECT last_seen_at FROM collector_nodes WHERE id=?",java.sql.Timestamp.class,node));}
 @Test void noOuterTransactionReadonlyOrForgedParsedBodyCannotWrite(){assertThrows(IllegalStateException.class,()->store.latest(node,1));tx.setReadOnly(true);assertThrows(IllegalStateException.class,()->save(now,10));tx.setReadOnly(false);var value=body(now,10);var forged=new CollectorHeartbeatTelemetry.Parsed(value.sample(),value.canonical(),"0".repeat(64));assertThrows(IllegalStateException.class,()->tx.execute(s->store.save(node,1,forged,now)));assertNull(tx.execute(s->store.latest(node,1)));}
}
